CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('owner','cashier','stock') NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(190) NOT NULL,category VARCHAR(80) NOT NULL,brand VARCHAR(80) DEFAULT '',unit VARCHAR(30) NOT NULL,barcode VARCHAR(80) DEFAULT '',image VARCHAR(255) DEFAULT '',cost DECIMAL(12,2) NOT NULL,price DECIMAL(12,2) NOT NULL,stock DECIMAL(12,3) NOT NULL DEFAULT 0,min_stock DECIMAL(12,3) NOT NULL DEFAULT 5,pack_size DECIMAL(12,3) NOT NULL DEFAULT 1,active BOOLEAN DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,phone VARCHAR(40) DEFAULT '',address TEXT,credit_limit DECIMAL(12,2) NOT NULL DEFAULT 5000);
CREATE TABLE IF NOT EXISTS suppliers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,phone VARCHAR(40) DEFAULT '',address TEXT);
CREATE TABLE IF NOT EXISTS documents(id INT AUTO_INCREMENT PRIMARY KEY,kind ENUM('sale','quote','purchase') NOT NULL,customer_id INT NULL,supplier_id INT NULL,user_id INT NOT NULL,total DECIMAL(12,2) NOT NULL,discount DECIMAL(12,2) NOT NULL DEFAULT 0,paid DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('open','converted','returned') DEFAULT 'open',due_date DATE NULL,note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS `lines`(id INT AUTO_INCREMENT PRIMARY KEY,document_id INT NOT NULL,product_id INT NOT NULL,name VARCHAR(190) NOT NULL,qty DECIMAL(12,3) NOT NULL,price DECIMAL(12,2) NOT NULL,cost DECIMAL(12,2) NOT NULL,FOREIGN KEY(document_id) REFERENCES documents(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS payments(id INT AUTO_INCREMENT PRIMARY KEY,document_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,method ENUM('cash','card','transfer') NOT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS movements(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT NOT NULL,qty DECIMAL(12,3) NOT NULL,reason VARCHAR(190) NOT NULL,user_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,label VARCHAR(190) NOT NULL,category VARCHAR(80) NOT NULL,amount DECIMAL(12,2) NOT NULL,expense_date DATE NOT NULL,user_id INT NOT NULL);
